86	/**
87	 * Add support for our legacy ":::note Title" admonition syntax
88	 * Not supported by https://github.com/remarkjs/remark-directive
89	 * Syntax is transformed to ":::note[Title]" (container directive label)
90	 * See https://talk.commonmark.org/t/generic-directives-plugins-syntax/444
91	 *
92	 * @param content
93	 * @param admonitionContainerDirectives
94	 */
95	export function admonitionTitleToDirectiveLabel(
96	  content: string,
97	  admonitionContainerDirectives: string[],
98	): string {
99	  // this will also process ":::note Title" inside docs code blocks
100	  // good enough: we fixed older versions docs to not be affected
101	
102	  const directiveNameGroup = `(${admonitionContainerDirectives.join('|')})`;
103	  const regexp = new RegExp(
104	    `^(?<quote>(> ?)*)(?<indentation>( +|\t+))?(?<directive>:{3,}${directiveNameGroup}) +(?<title>.*)$`,
105	    'gm',
106	  );
107	
108	  return content.replaceAll(regexp, (substring, ...args: any[]) => {
109	    const groups = args.at(-1);
110	
111	    return `${groups.quote ?? ''}${groups.indentation ?? ''}${
112	      groups.directive
113	    }[${groups.title}]`;
114	  });
115	}
