31	/**
32	 * We only handle the "paths to watch" because these are the paths where the
33	 * markdown files are. Also we don't want to transform the site md docs that do
34	 * not belong to a content plugin. For example ./README.md should not be
35	 * transformed
36	 */
37	async function getPathsToWatch(siteDir: string): Promise<string[]> {
38	  const context = await loadContext({siteDir});
39	  const plugins = await initPlugins(context);
40	  return plugins.flatMap((plugin) => plugin.getPathsToWatch?.() ?? []);
41	}
