43	export async function writeHeadingIds(
44	  siteDirParam: string = '.',
45	  files: string[] = [],
46	  options: WriteHeadingIDOptions = {},
47	): Promise<void> {
48	  const siteDir = await fs.realpath(siteDirParam);
49	
50	  const patterns = files.length ? files : await getPathsToWatch(siteDir);
51	
52	  const markdownFiles = await safeGlobby(patterns, {
53	    expandDirectories: ['**/*.{md,mdx}'],
54	  });
55	
56	  if (markdownFiles.length === 0) {
57	    logger.warn`No markdown files found in siteDir path=${siteDir} for patterns: ${patterns}`;
58	    return;
59	  }
60	
61	  const result = await Promise.all(
62	    markdownFiles.map((p) => transformMarkdownFile(p, options)),
63	  );
64	
65	  const pathsModified = result.filter(Boolean) as string[];
66	
67	  if (pathsModified.length) {
68	    logger.success`Heading ids added to Markdown files (number=${`${pathsModified.length}/${markdownFiles.length}`} files): ${pathsModified}`;
69	  } else {
70	    logger.warn`number=${
71	      markdownFiles.length
72	    } Markdown files already have explicit heading IDs. If you intend to overwrite the existing heading IDs, use the code=${'--overwrite'} option.`;
73	  }
74	}
